from typing import List

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        def dfs(rem: int) -> int:
            if rem == 0:
                return 0
            if rem < 0:
                return float("inf")
            return 1 + min(dfs(rem - coin) for coin in coins)

        ans = dfs(amount)
        return -1 if ans == float("inf") else ans

