from typing import List

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        memo = {}

        def dfs(rem: int) -> int:
            if rem == 0:
                return 0
            if rem < 0:
                return float("inf")
            if rem not in memo:
                memo[rem] = 1 + min(dfs(rem - coin) for coin in coins)
            return memo[rem]

        ans = dfs(amount)
        return -1 if ans == float("inf") else ans

